package uusni

import (
	"bytes"
	"encoding/hex"
	"errors"
	"io"
	"net"
	"strings"
	"testing"
)

func fixture() Config {
	return Config{Server: "203.0.113.10", Port: 5556, ObfsKey: 77, SNICrypt: true}
}

func TestIndependentWireVectors(t *testing.T) {
	config := fixture()
	header, err := Header(config, "example.com", 443)
	if err != nil {
		t.Fatal(err)
	}
	// Synthetic vector independently checked with Python/OpenSSL and C
	// libmbedcrypto in the protocol handbook, not generated by this encoder.
	want, _ := hex.DecodeString("5555010101bb2c1000000000000000000000000000000000f174c41f691bd3bbcdacc5f0c241967be9b39b10be5f6f914f6d76")
	for i := range want {
		want[i] ^= 77
	}
	if !bytes.Equal(header, want) {
		t.Fatalf("encrypted header: %x, want %x", header, want)
	}
	config.SNICrypt = false
	for key := 0; key <= 255; key++ {
		config.ObfsKey = key
		header, err = Header(config, "example.com", 80)
		if err != nil {
			t.Fatal(err)
		}
		clear, _ := hex.DecodeString("5555010000500b6578616d706c652e636f6d")
		for i := range clear {
			clear[i] ^= byte(key)
		}
		if !bytes.Equal(header, clear) {
			t.Fatalf("XOR key %d: target port 80/header changed", key)
		}
	}
}

func TestAddressLimitsAndKeys(t *testing.T) {
	config := fixture()
	if key := addressKey(config); string(key[:]) != "203.0.113.10:555" {
		t.Fatal("long key must be truncated")
	}
	config.Server, config.Port = "1.2.3.4", 8
	if key := addressKey(config); string(key[:]) != "1.2.3.4:8UUUUUUU" {
		t.Fatal("short key must be U-padded")
	}
	host := strings.Repeat("a", 63) + "." + strings.Repeat("b", 63) + "." + strings.Repeat("c", 63) + "." + strings.Repeat("d", 30)
	if _, err := Header(config, host, 443); err != nil {
		t.Fatal("222 bytes must fit:", err)
	}
	if _, err := Header(config, host+"d", 443); err == nil {
		t.Fatal("223 encrypted bytes must not wrap the length")
	}
	config.SNICrypt = false
	host = strings.Repeat("a", 63) + "." + strings.Repeat("b", 63) + "." + strings.Repeat("c", 63) + "." + strings.Repeat("d", 61)
	if _, err := Header(config, host, 443); err != nil {
		t.Fatal("253 clear bytes must fit:", err)
	}
	if _, err := Header(config, host+"d", 443); err == nil {
		t.Fatal("overlong domain accepted")
	}
	for _, host := range []string{"example.com.", "127.0.0.1", "localhost"} {
		if _, err := Header(config, host, 443); err != nil {
			t.Fatalf("valid target %q: %v", host, err)
		}
	}
	for _, host := range []string{"", ".", "::1", "[::1]", "-bad.test", "bad-.test", "a..b", "a/b", "a@b", "a\x00b", "a\rb", "中文.example", strings.Repeat("a", 64) + ".test"} {
		if _, err := Header(config, host, 443); err == nil {
			t.Fatalf("invalid target %q accepted", host)
		}
	}
	if _, err := Header(config, "example.com", 0); err == nil {
		t.Fatal("zero destination port accepted")
	}
	for _, change := range []func(*Config){
		func(c *Config) { c.Server = "node.example" }, func(c *Config) { c.Server = "::1" },
		func(c *Config) { c.Server = "0.0.0.0" }, func(c *Config) { c.Server = "224.0.0.1" },
		func(c *Config) { c.Port = 0 }, func(c *Config) { c.Port = 65536 },
		func(c *Config) { c.ObfsKey = -1 }, func(c *Config) { c.ObfsKey = 256 },
	} {
		config := fixture()
		change(&config)
		if config.Validate() == nil {
			t.Fatalf("invalid node accepted: %+v", config)
		}
	}
}

type shortConn struct {
	net.Conn
	bytes.Buffer
	limit int
	err   error
	zero  bool
}

func (c *shortConn) Write(b []byte) (int, error) {
	if c.zero {
		return 0, nil
	}
	n := len(b)
	if n > c.limit {
		n = c.limit
	}
	c.Buffer.Write(b[:n])
	return n, c.err
}
func (c *shortConn) Read(b []byte) (int, error) { return c.Buffer.Read(b) }

func TestXORShortWritesAndCallerBuffers(t *testing.T) {
	input := bytes.Repeat([]byte{0, 1, 127, 128, 255}, 30000)
	original := bytes.Clone(input)
	raw := &shortConn{limit: 7}
	conn := &Conn{Conn: raw, key: 77}
	if conn.ReaderReplaceable() || conn.WriterReplaceable() {
		t.Fatal("copy/splice can bypass XOR")
	}
	n, err := conn.Write(input)
	if err != nil || n != len(input) || !bytes.Equal(input, original) {
		t.Fatal("write count, error or caller mutation", n, err)
	}
	for i, b := range raw.Bytes() {
		if b != input[i]^77 {
			t.Fatal("chunk XOR mismatch", i)
		}
	}
	got, err := io.ReadAll(conn)
	if err != nil || !bytes.Equal(got, input) {
		t.Fatal("download XOR mismatch", err)
	}
	raw.zero = true
	if _, err := conn.Write([]byte("x")); !errors.Is(err, io.ErrShortWrite) {
		t.Fatal("zero writer must fail", err)
	}
	raw.zero = false
	raw.err = io.ErrClosedPipe
	if n, err := conn.Write([]byte("0123456789")); n != 7 || !errors.Is(err, io.ErrClosedPipe) {
		t.Fatal("partial error must preserve byte count", n, err)
	}
}
